import json

schema = {"name": str, "age": int, "member": bool}
replies = [
    '{"name": "Asha", "age": "42", "member": true}',
    '{"name": "Ravi", "member": false}',
    '{"name": "Kiran", "age": "forty", "member": true}',
]

accepted, rejected = [], []
for raw in replies:
    data = json.loads(raw)
    try:
        clean = {}
        for field, typ in schema.items():
            if field not in data:
                raise ValueError(f"missing {field}")
            clean[field] = typ(data[field])          # coerce "42" -> 42
        accepted.append(clean)
    except ValueError as err:
        rejected.append((data["name"], str(err)))

print("accepted:", accepted)
print("rejected:", rejected)                      # retry these with the error message
